// Consulta por partes: si el panel vuelve a preguntar trae jobId/location (solo letras, números, - y _).
const _qp = $('Webhook: listar facturas').first().json.query || {};
const _jobId = String(_qp.jobId || '').replace(/[^A-Za-z0-9_-]/g, '');
const _location = String(_qp.location || '').replace(/[^A-Za-z0-9-]/g, '') || 'us-east1';
const nitEmisor = String($input.first().json.query.nitEmisor || '').replace(/\D/g, '');
if (!nitEmisor) {
  throw new Error('Falta el parámetro nitEmisor en la consulta.');
}

const columnas = [
  'nit_emisor', 'nit_pagador', 'pagador', 'numero_factura',
  'fecha_vencimiento', 'valor_neto', 'valor_neto_calculado', 'cufe'
].join(', ');

const tabla = '`inlaid-stack-375114.analytics_data_products.opportunity_mapping`';

// nit_emisor se limpia a solo dígitos para que coincida sin importar si viene con puntos o DV.
const bqQuery = 'SELECT ' + columnas + ' FROM ' + tabla +
  " WHERE REGEXP_REPLACE(CAST(nit_emisor AS STRING), r'[^0-9]', '') = '" + nitEmisor + "'";

return [{ json: { jobId: _jobId, location: _location, nitEmisor, bqQuery } }];

// Consulta por partes: BigQuery aún no termina -> el panel vuelve a preguntar con este jobId.
const _r = $input.first().json || {};
if (_r.jobComplete === false && _r.jobReference && _r.jobReference.jobId) {
  return [{ json: { pendiente: true, jobId: _r.jobReference.jobId, location: _r.jobReference.location || 'us-east1' } }];
}
const resp = $input.first().json;
const fields = (resp.schema && resp.schema.fields) || [];
const rawRows = resp.rows || [];

const rows = rawRows.map(row => {
  const obj = {};
  row.f.forEach((cell, i) => { obj[fields[i].name] = cell.v; });
  return obj;
});

// Valor: la API de BigQuery devuelve los números como texto (ej. "2.6283471E7").
// Si no es un número directo, se limpia como en la calculadora (puntos de miles, coma decimal).
function parseValor(v){
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(v);
  if (isFinite(n)) return n;
  const s = String(v).replace(/[^0-9.,-]/g, '').replace(/\./g, '').replace(',', '.');
  return parseFloat(s) || 0;
}
// Fecha: puede llegar como 2026-08-10 o como 2026.08.10 (según la calculadora-mapeo). Se deja en AAAA-MM-DD.
function parseFecha(v){
  const s = String(v || '').trim();
  const m = s.match(/^(\d{4})[-.\/](\d{1,2})[-.\/](\d{1,2})/);
  if (m) return m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0');
  const m2 = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m2) return m2[3] + '-' + m2[2].padStart(2, '0') + '-' + m2[1].padStart(2, '0');
  return s;
}

const facturas = rows.map(r => ({
  nitPagador: String(r.nit_pagador || '').replace(/\D/g, ''),
  pagador: r.pagador || '',
  folio: r.numero_factura || '',
  vencimiento: parseFecha(r.fecha_vencimiento),
  // Pruebas piloto (5-nov-2026): se usa el valor neto calculado de opportunity_mapping (valor neto menos retenciones);
  // si viene vacío, el valor neto. Así no hay que corregir valores a mano en la operación.
  valor: (r.valor_neto_calculado !== null && r.valor_neto_calculado !== undefined && r.valor_neto_calculado !== '') ? parseValor(r.valor_neto_calculado) : parseValor(r.valor_neto),
  valorNeto: parseValor(r.valor_neto),
  cufe: r.cufe || ''
}));

return [{ json: { encontrado: facturas.length > 0, facturas } }];
